import unittest
from stringutil import slugify

class TestSlugify(unittest.TestCase):
    def test_normal_two_word_input(self):
        self.assertEqual(slugify("Hello World"), "hello-world")

    def test_input_with_extra_spaces(self):
        self.assertEqual(slugify("  Hello  World  "), "hello-world")

    def test_input_already_lowercase_no_spaces(self):
        self.assertEqual(slugify("hello-world"), "hello-world")

if __name__ == '__main__':
    unittest.main()

"""String helpers."""


def slugify(text):
    """Lowercase text, replace spaces with hyphens, strip edges."""
    return "-".join(text.strip().lower().split())

